import sys


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    if sys.getrecursionlimit() < 20000:
        sys.setrecursionlimit(20000)

    def tokenize(s: str) -> list[str]:
        tokens: list[str] = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(s[i:j])
                i = j
            elif ch.isalpha():
                j = i + 1
                while j < n and s[j].isalnum():
                    j += 1
                tokens.append(s[i:j])
                i = j
            elif ch == "<" and i + 1 < n and s[i + 1] in ("=", ">"):
                tokens.append(s[i : i + 2])
                i += 2
            elif ch == ">" and i + 1 < n and s[i + 1] == "=":
                tokens.append(">=")
                i += 2
            else:
                tokens.append(ch)
                i += 1
        return tokens

    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def trunc_div(a: int, b: int) -> int | str:
        if b == 0:
            return "#DIV/0!"
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    def eval_cell(name: str) -> int | str:
        if name in memo:
            return memo[name]
        if name not in cells:
            return 0
        if name in visiting:
            return "#CYCLE!"

        raw = cells[name]
        if not raw.startswith("="):
            val = int(raw)
            memo[name] = val
            return val

        visiting.add(name)
        tokens = tokenize(raw[1:])
        pos = 0

        def peek(offset: int = 0) -> str | None:
            idx = pos + offset
            return tokens[idx] if idx < len(tokens) else None

        def consume() -> str:
            nonlocal pos
            tok = tokens[pos]
            pos += 1
            return tok

        def parse_formula(active: bool) -> int | str:
            val = parse_term(active)
            while peek() in ("+", "-"):
                op = consume()
                rhs_active = active and not isinstance(val, str)
                rhs = parse_term(rhs_active)
                if rhs_active:
                    if isinstance(rhs, str):
                        val = rhs
                    elif op == "+":
                        val = val + rhs  # type: ignore[operator]
                    else:
                        val = val - rhs  # type: ignore[operator]
            return val

        def parse_term(active: bool) -> int | str:
            val = parse_unary(active)
            while peek() in ("*", "/"):
                op = consume()
                rhs_active = active and not isinstance(val, str)
                rhs = parse_unary(rhs_active)
                if rhs_active:
                    if isinstance(rhs, str):
                        val = rhs
                    elif op == "*":
                        val = val * rhs  # type: ignore[operator]
                    else:
                        val = trunc_div(val, rhs)  # type: ignore[arg-type]
            return val

        def parse_unary(active: bool) -> int | str:
            if peek() == "-":
                consume()
                val = parse_unary(active)
                if active and not isinstance(val, str):
                    return -val
                return val
            return parse_atom(active)

        def parse_atom(active: bool) -> int | str:
            tok = peek()
            if tok == "(":
                consume()
                val = parse_formula(active)
                consume()  # ')'
                return val
            if tok is not None and tok[0].isdigit():
                consume()
                return int(tok) if active else 0
            if tok in ("SUM", "MIN", "MAX") and peek(1) == "(":
                return parse_agg(active)
            if tok == "IF" and peek(1) == "(":
                return parse_if(active)
            consume()
            return eval_cell(tok) if active and tok is not None else 0

        def parse_agg(active: bool) -> int | str:
            fn = consume()
            consume()  # '('
            err: str | None = None
            acc: int | None = None

            def add_val(v: int | str) -> None:
                nonlocal err, acc
                if err is not None:
                    return
                if isinstance(v, str):
                    err = v
                elif acc is None:
                    acc = v
                elif fn == "SUM":
                    acc += v
                elif fn == "MIN":
                    if v < acc:
                        acc = v
                else:
                    if v > acc:
                        acc = v

            while True:
                t0, t1 = peek(0), peek(1)
                if t0 is not None and t1 == ":":
                    c1_name = consume()
                    consume()  # ':'
                    c2_name = consume()
                    if active and err is None:
                        c1, r1 = ord(c1_name[0]), int(c1_name[1:])
                        c2, r2 = ord(c2_name[0]), int(c2_name[1:])
                        for r in range(min(r1, r2), max(r1, r2) + 1):
                            for c in range(min(c1, c2), max(c1, c2) + 1):
                                cname = f"{chr(c)}{r}"
                                if cname in cells:
                                    add_val(eval_cell(cname))
                                    if err is not None:
                                        break
                            if err is not None:
                                break
                else:
                    v = parse_formula(active and err is None)
                    if active and err is None:
                        add_val(v)

                if peek() == ",":
                    consume()
                else:
                    break

            consume()  # ')'
            if not active:
                return 0
            if err is not None:
                return err
            return 0 if acc is None else acc

        def parse_if(active: bool) -> int | str:
            consume()  # 'IF'
            consume()  # '('
            lv = parse_formula(active)
            op = consume()
            rv = parse_formula(active and not isinstance(lv, str))
            consume()  # ','

            cond_ok = active and not isinstance(lv, str) and not isinstance(rv, str)
            cond = False
            if cond_ok:
                if op == "=":
                    cond = lv == rv
                elif op == "<>":
                    cond = lv != rv
                elif op == "<":
                    cond = lv < rv  # type: ignore[operator]
                elif op == "<=":
                    cond = lv <= rv  # type: ignore[operator]
                elif op == ">":
                    cond = lv > rv  # type: ignore[operator]
                elif op == ">=":
                    cond = lv >= rv  # type: ignore[operator]

            tv = parse_formula(cond_ok and cond)
            consume()  # ','
            ev = parse_formula(cond_ok and not cond)
            consume()  # ')'

            if not active:
                return 0
            if isinstance(lv, str):
                return lv
            if isinstance(rv, str):
                return rv
            return tv if cond else ev

        res = parse_formula(True)
        visiting.remove(name)
        memo[name] = res
        return res

    return {name: eval_cell(name) for name in cells}
